-- match each Blocker to the nearest saved x/z (not by order, in case parts were added/removed)
local function restore(root, rows)
	local done = 0
	for _, b in ipairs(root:GetDescendants()) do
		if b:IsA("BasePart") and b.Name == "Blocker" then
			local best, bd
			for _, r in ipairs(rows) do
				local d = (Vector2.new(b.Position.X, b.Position.Z) - Vector2.new(r[1], r[2])).Magnitude
				if not bd or d < bd then best, bd = r, d end
			end
			if best and bd < 0.5 then
				b.Size = Vector3.new(b.Size.X, best[3], b.Size.Z)
				b.Position = Vector3.new(b.Position.X, best[4], b.Position.Z)
				done += 1
			end
		end
	end
	print("restored " .. done .. " Blocker in " .. root:GetFullName())
end
restore(workspace.LayoutDecor.ShopPlazaDecor.Fence, data.shop)
restore(workspace.LayoutDecor.ActivityPlazaDecor.Fence, data.activity)
